JHB.glossary = [
  /* ───────── 증상 ───────── */
  { term: '양성 증상', en: 'positive symptoms', def: '원래 없어야 할 것이 더해진 증상. 환각, 망상, 와해된 말과 행동.', related: ['positive-overview', 'hallucination-overview', 'delusion-overview'] },
  { term: '음성 증상', en: 'negative symptoms', def: '원래 있어야 할 것이 줄어든 증상. 의욕·즐거움·말·표정·관계가 줄어듦.', related: ['negative-overview', 'primary-secondary-negative'] },
  { term: '인지 증상', en: 'cognitive symptoms', def: '주의·기억·처리 속도처럼 생각하는 힘이 떨어지는 증상. 양성 증상이 가라앉은 뒤에도 남아 공부·일·관계를 어렵게 함.', related: ['cognitive-overview', 'cognitive-domains'] },
  { term: '환각', en: 'hallucination', def: '바깥 자극이 없는데도 실제처럼 보이고, 들리고, 냄새 나고, 몸에 느껴지는 경험. 실제 자극을 다르게 지각하는 착각과 구분됨.', related: ['hallucination-overview'] },
  { term: '환청', en: 'auditory hallucination', def: '실제 소리가 없는데 목소리나 소리가 들리는 경험. 조현병에서 가장 흔한 환각.', related: ['auditory-hallucination', 'living-with-voices'] },
  { term: '환시', en: 'visual hallucination', def: '눈앞에 없는 사람·동물·그림자·빛 같은 것이 보이는 환각. 조현병에서는 대부분 환청과 함께 나타남.', related: ['visual-hallucination'] },
  { term: '환촉', en: 'tactile hallucination', def: '닿는 것이 없는데 피부에 무언가 닿거나 기어가는 느낌이 드는 환각. 없는 냄새가 나는 환후, 없는 맛이 나는 환미와 함께 비교적 드문 환각에 속함.', related: ['other-hallucinations'] },
  { term: '신체 환각', en: 'somatic hallucination', def: '장기가 움직이거나 뼈가 뒤틀리는 것처럼 몸 안에서 느껴지는 환각. 피부 표면에서 느껴지는 환촉과 구분됨.', related: ['somatic-hallucination'] },
  { term: '망상', en: 'delusion', def: '분명한 반대 증거가 있어도 바뀌지 않는 확고한 믿음. 사소한 것에 과한 의미가 붙고 성급한 결론이 쌓이며 만들어짐.', related: ['delusion-overview'] },
  { term: '피해망상', en: 'persecutory delusion', def: '누군가 나를 일부러 해치려 한다는 확고한 믿음. 조현병에서 가장 흔한 망상.', related: ['persecutory-delusion'] },
  { term: '관계망상', en: 'delusion of reference', def: '나와 상관없는 일·말·방송이 나를 겨냥한 신호라고 확신하는 망상. 반대 증거에 흔들리는 가벼운 느낌은 관계 사고라 하며 누구나 겪음.', related: ['referential-delusion'] },
  { term: '과대망상', en: 'grandiose delusion', def: '나에게 남다른 능력·재산·정체·사명이 있다는 확고한 믿음. 조현병과 양극성 장애의 조증에서 나타남.', related: ['grandiose-delusion', 'vs-bipolar'] },
  { term: '조종망상', en: 'delusion of control', def: '내 몸의 움직임·감정·충동이 외부의 힘에 의해 만들어진다고 확신하는 망상. "내가 했다"는 느낌의 상실이 핵심.', related: ['control-delusion', 'self-tickling'] },
  { term: '사고주입', en: 'thought insertion', def: '내 것이 아닌 생각이 밖에서 머릿속으로 들어온다고 확신하는 경험. 생각이 새어 나간다는 사고전파, 빼앗긴다는 사고탈취와 함께 묶임.', related: ['thought-interference'] },
  { term: '1급 증상', en: 'first-rank symptoms', def: '독일 정신과 의사 슈나이더가 조현병을 가르는 데 특히 쓸모 있다고 본 증상 묶음. 사고주입·전파·탈취, 조종망상 등이 들어가며 지금은 다른 증상과 같은 무게로 봄.', related: ['thought-interference', 'control-delusion'] },
  { term: '허무망상', en: 'nihilistic delusion', def: '나, 내 몸의 일부, 또는 세상이 존재하지 않는다는 믿음. 내 몸에 큰 문제가 있다는 신체망상과 겹친 극단적 형태를 코타르 증후군이라 함.', related: ['somatic-nihilistic-delusion'] },
  { term: '질투망상', en: 'delusional jealousy (Othello syndrome)', def: '증거가 없는데도 배우자나 연인이 바람을 피운다고 확신하는 망상. 오셀로 증후군이라고도 함.', related: ['jealousy-erotomanic-delusion'] },
  { term: '색정망상', en: 'erotomania (de Clérambault syndrome)', def: '누군가, 흔히 지위가 더 높다고 여기는 사람이 나를 사랑한다고 확신하는 망상. 드 클레랑보 증후군이라고도 함.', related: ['jealousy-erotomanic-delusion'] },
  { term: '종교망상', en: 'religious delusion', def: '"신이 보낸 사람이다", "악마가 몸에 들어왔다"처럼 종교적 내용을 담은 망상. 신앙 자체는 망상이 아님.', related: ['religious-delusion'] },
  { term: '사고 장애', en: 'formal thought disorder', def: '생각의 내용이 아니라 생각이 이어지는 방식이 흐트러져 말을 따라가기 어려워지는 증상. 형식적 사고 장애라고도 함.', related: ['thought-disorder'] },
  { term: '연상 이완', en: 'loosening of associations', def: '생각 사이의 연결이 느슨해져 관련 없는 내용으로 건너뛰는 사고 장애. 탈선과 거의 같은 뜻으로 쓰임.', related: ['thought-disorder'] },
  { term: '말비빔', en: 'word salad', def: '지리멸렬의 가장 심한 형태. 문법이 사라지고 단어들이 무작위로 뒤섞인 말.', related: ['thought-disorder'] },
  { term: '신어조작', en: 'neologism', def: '새로운 단어를 만들어 자기만의 뜻으로 쓰는 것. 사고 장애의 한 형태.', related: ['thought-disorder'] },
  { term: '사고 차단', en: 'thought blocking', def: '말하다가 생각이 갑자기 끊겨 멈추는 것. 당사자는 생각을 빼앗긴 것처럼 느끼기도 함.', related: ['thought-disorder', 'thought-interference'] },
  { term: '와해된 행동', en: 'disorganized behavior', def: '행동이 목표를 잃고 상황과 맞지 않게 흐트러지는 증상. 옷차림·위생이 무너지고 일상을 꾸리기 어려워짐.', related: ['disorganized-behavior'] },
  { term: '긴장증', en: 'catatonia', def: '몸이 굳어 움직이지 않거나 목적 없이 격하게 움직이는 증상 묶음. 조현병 외에 우울증·조증·뇌 질환에서도 생기고 벤조디아제핀과 ECT에 반응이 좋음.', related: ['catatonia', 'ect'] },
  { term: '납굴증', en: 'waxy flexibility', def: '긴장증 징후의 하나. 팔다리를 움직이면 밀랍처럼 가볍고 고른 저항이 느껴짐.', related: ['catatonia'] },
  { term: '무의욕', en: 'avolition', def: '목표를 향해 움직이기 시작하고 이어 가는 힘이 줄어드는 음성 증상. "하기 싫다"보다 "하고 싶은데 시작이 안 된다"에 가까움.', related: ['avolition', 'negative-self-help'] },
  { term: '무쾌감', en: 'anhedonia', def: '즐거움을 느끼는 힘이 줄어드는 음성 증상. 조현병에서는 막상 할 때보다 미리 기대하는 즐거움이 주로 줄어듦.', related: ['anhedonia'] },
  { term: '무언증', en: 'alogia', def: '말의 양이 줄고 내용이 빈약해지는 음성 증상. 말을 안 하는 것이 아니라 말이 잘 나오지 않는 상태. 알로기아라고도 하며, 말을 아예 하지 않는 함구증(mutism)과는 다름.', related: ['alogia', 'thought-disorder'] },
  { term: '정서 둔마', en: 'blunted affect', def: '감정이 표정·목소리·몸짓으로 드러나는 정도가 줄어드는 음성 증상. 안에서 느끼는 감정은 보존된 경우가 많음.', related: ['blunted-affect'] },
  { term: '비사회성', en: 'asociality', def: '사람과 어울리고 관계를 맺으려는 마음 자체가 줄어드는 음성 증상. 불안이나 의심 때문에 피하는 것과 다름.', related: ['asociality', 'loneliness-relationships'] },
  { term: '일차·이차 음성 증상', en: 'primary and secondary negative symptoms', def: '병 자체에서 나오는 음성 증상이 일차, 약 부작용·우울·망상·환경 때문에 생긴 것이 이차. 이차는 원인을 다루면 좋아지는 경우가 많음.', related: ['primary-secondary-negative', 'negative-treatment-difficulty'] },
  { term: '결핍 증후군', en: 'deficit syndrome', def: '다른 원인 없이 1년 이상 이어지는 일차 음성 증상을 가진 조현병의 한 아형. "별개의 병"이라는 가설은 아직 논쟁 중.', related: ['deficit-syndrome'] },
  { term: '사회 인지', en: 'social cognition', def: '표정에서 감정을 읽고, 말 뒤의 의도를 짐작하고, 분위기를 파악하는 능력. 일상 기능을 강하게 좌우함.', related: ['social-cognition'] },
  { term: '병식', en: 'insight', def: '자신에게 병이 있고 치료가 필요하다는 것을 아는 정도. 낮으면 치료 중단과 재발로 이어지기 쉬움.', related: ['insight', 'leap-communication'] },

  /* ───────── 진단·평가·경과 ───────── */
  { term: '정신증', en: 'psychosis', def: '환각·망상 같은 정신병 증상이 나타나는 상태. 조현병 외에 기분장애·물질·뇌 질환에서도 생기며, 조현병은 정신증에 다른 증상이 더해진 진단.', related: ['dopamine-hypothesis', 'rule-out-conditions', 'spectrum'] },
  { term: 'DSM-5-TR', en: 'Diagnostic and Statistical Manual of Mental Disorders, 5th ed., Text Revision', def: '미국정신의학회(APA)가 만드는 정신질환 진단 편람의 2022년 개정판. 조현병을 A~F 여섯 기준으로 정의함.', related: ['dsm5-criteria'] },
  { term: 'ICD-11', en: 'International Classification of Diseases, 11th Revision', def: '세계보건기구의 국제질병분류 11판. 조현병 코드는 6A20이고, 아형 대신 경과·증상 지정자를 붙임.', related: ['icd11'] },
  { term: '조현정동장애', en: 'schizoaffective disorder', def: '조현병의 정신병 증상과 조증·주요우울 삽화가 한 사람에게 함께 나타나는 진단. DSM-5부터 기분 삽화가 전체 병 기간의 과반이어야 함.', related: ['vs-schizoaffective'] },
  { term: '조현양상장애', en: 'schizophreniform disorder', def: '조현병과 같은 증상이 1개월 이상 6개월 미만 이어지는 경우의 진단. 6개월을 넘기면 조현병으로 바뀜.', related: ['vs-brief-psychotic'] },
  { term: '단기 정신병적 장애', en: 'brief psychotic disorder', def: '정신병 증상이 하루 이상 1개월 미만 이어진 뒤 완전히 가라앉고 발병 전 기능으로 돌아오는 경우.', related: ['vs-brief-psychotic'] },
  { term: '망상장애', en: 'delusional disorder', def: '망상이 1개월 이상 이어지지만 환각·와해·음성 증상은 두드러지지 않고, 망상과 관련 없는 영역의 기능은 비교적 유지되는 병.', related: ['vs-delusional-disorder'] },
  { term: '물질 유발 정신병', en: 'substance-induced psychotic disorder', def: '대마·각성제·환각제·알코올 금단, 스테로이드 같은 처방약이 일으키는 정신병 증상. 물질을 끊고 한 달쯤 지나도 남으면 일차 정신병을 의심함.', related: ['vs-substance-induced', 'cannabis'] },
  { term: '조현병 스펙트럼', en: 'schizophrenia spectrum', def: '조현병을 경계가 뚜렷한 하나의 병이 아니라 가벼운 특성부터 심한 장애까지 이어진 연속선의 한 구간으로 보는 관점.', related: ['spectrum', 'controversies'] },
  { term: '항-NMDA 수용체 뇌염', en: 'anti-NMDA receptor encephalitis', def: '자기 몸의 항체가 NMDA 수용체를 공격하는 뇌염. 정신과 증상으로 시작하는 경우가 많아 첫 진단 때 걸러야 할 질환.', related: ['rule-out-conditions', 'glutamate-hypothesis'] },
  { term: 'PANSS', en: 'Positive and Negative Syndrome Scale', def: '양성·음성 증상과 일반 정신병리를 면담으로 평가하는 30항목 척도. 조현병 임상시험 대부분이 효과를 이 척도로 잼.', related: ['panss', 'negative-scales'] },
  { term: 'BNSS', en: 'Brief Negative Symptom Scale', def: '간이 음성 증상 척도. 13항목으로 음성 증상 다섯 영역을 모두 재는 2세대 척도로, 짧아서 임상시험에 쓰기 좋음.', related: ['negative-scales'] },
  { term: 'AIMS', en: 'Abnormal Involuntary Movement Scale', def: '이상운동 척도. 의사가 얼굴·입·손·발·몸통의 움직임을 관찰해 지연성 운동장애를 확인하는 짧은 검사.', related: ['eps'] },
  { term: '임상적 고위험군', en: 'clinical high risk (CHR), ultra-high risk (UHR)', def: '약화된 정신병 증상, 짧고 간헐적인 정신병 증상, 유전 위험과 기능 저하 가운데 하나에 해당해 정신증 위험이 높은 상태. CAARMS 같은 도구로 판단함.', related: ['prodrome', 'early-detection'] },
  { term: '전구기', en: 'prodrome', def: '뚜렷한 정신병 증상이 나타나기 전, 수개월에서 몇 년에 걸쳐 미묘한 변화가 먼저 보이는 시기.', related: ['prodrome'] },
  { term: '첫 삽화', en: 'first episode psychosis', def: '처음으로 뚜렷한 정신병 증상이 나타나 치료를 시작하는 시기. 약에 가장 잘 반응하는 시기로 알려짐.', related: ['first-episode'] },
  { term: '정신병 미치료 기간(DUP)', en: 'duration of untreated psychosis (DUP)', def: '정신병 증상이 처음 나타난 때부터 제대로 된 치료를 시작하기까지의 기간. 길수록 증상·기능·삶의 질이 나쁜 경향이 있음.', related: ['first-episode', 'early-detection', 'adolescent-onset'] },
  { term: '안정기', en: 'stable phase', def: '급성 증상이 가라앉은 뒤 이어지는 긴 시기. 약한 증상이나 음성·인지 증상이 남는 잔류기와 함께 재활과 재발 예방의 시기.', related: ['stable-phase'] },
  { term: '관해', en: 'remission', def: '핵심 증상이 모두 "경미" 이하인 상태가 6개월 이상 이어지는 것. 증상이 0이 아니라 일상을 방해하지 않을 만큼 가벼운 상태.', related: ['stable-phase', 'recovery', 'prognosis'] },
  { term: '재발', en: 'relapse', def: '안정됐던 증상이 다시 심해지는 것. 수면 변화, 예민함 같은 신호가 몇 주 전에 먼저 오는 경우가 많음.', related: ['relapse-signs', 'relapse-prevention-plan'] },
  { term: '조기 경고 신호', en: 'early warning signs', def: '재발 몇 주 전부터 나타나는 불안·불면 같은 변화. 미리 알아 두고 계획을 세우면 재발을 막거나 가볍게 지날 수 있음.', related: ['relapse-signs', 'symptom-diary-tools', 'relapse-prevention-plan'] },
  { term: '회복', en: 'recovery', def: '증상과 기능이 기준을 넘어 유지되는 임상적 회복과, 증상이 있어도 의미 있는 삶을 살아가는 개인적 회복을 함께 가리킴.', related: ['recovery', 'recovery-commonalities'] },

  /* ───────── 약·부작용 ───────── */
  { term: '항정신병약', en: 'antipsychotic', def: '환각·망상의 힘을 빼는 약. 대부분은 뇌의 도파민 D2 수용체를 일정 비율 막는 방식이며, 1950년대 클로르프로마진에서 시작됐고 1세대와 2세대로 나눔.', related: ['antipsychotic-basics', 'first-generation', 'second-generation'] },
  { term: '1세대 항정신병약', en: 'first-generation antipsychotics', def: '1950년대에 나온 첫 세대 약. 도파민 D2 수용체를 강하게 막고, 추체외로 증상이 2세대보다 많음.', related: ['first-generation'] },
  { term: '2세대 항정신병약', en: 'second-generation (atypical) antipsychotics', def: '"비정형"이라고도 부르는 약들. 대체로 추체외로 증상이 적고 대사 부작용이 많지만, 약마다 성질이 크게 달라 한 집단으로 보기 어려움.', related: ['second-generation'] },
  { term: '부분 작용제', en: 'partial agonist', def: 'D2 수용체를 막기만 하지 않고 약하게 자극도 하는 약. 아리피프라졸·브렉스피프라졸·카리프라진이 여기에 속함.', related: ['aripiprazole', 'brexpiprazole', 'cariprazine'] },
  { term: '할로페리돌', en: 'haloperidol', def: '대표적인 1세대 항정신병약. 체중 증가는 적지만 떨림·뻣뻣함 같은 추체외로 증상이 많은 축.', related: ['haloperidol'] },
  { term: '리스페리돈', en: 'risperidone', def: 'D2·5-HT2A 수용체를 막는 2세대 항정신병약. 효과는 상위권이지만 프로락틴 상승이 약점.', related: ['risperidone'] },
  { term: '팔리페리돈', en: 'paliperidone', def: '리스페리돈의 활성 대사물을 약으로 만든 2세대 항정신병약. 1개월·3개월·6개월 간격 장기지속형 주사가 있음.', related: ['paliperidone', 'lai'] },
  { term: '올란자핀', en: 'olanzapine', def: '효과가 상위권인 2세대 항정신병약. 체중·혈당·지질 부작용이 가장 큰 축.', related: ['olanzapine', 'metabolic-side-effects'] },
  { term: '아리피프라졸', en: 'aripiprazole', def: '도파민 D2 수용체를 부분적으로 자극하는 2세대 항정신병약. 체중과 프로락틴에서 유리하지만 정좌불능이 약점.', related: ['aripiprazole'] },
  { term: '쿠에티아핀', en: 'quetiapine', def: 'D2 수용체를 짧고 약하게 잡는 2세대 항정신병약. 추체외로 증상은 거의 없지만 진정이 강함.', related: ['quetiapine'] },
  { term: '아미설프리드', en: 'amisulpride', def: '도파민 D2·D3 수용체만 골라 막는 2세대 항정신병약. 효과는 상위권이지만 프로락틴 상승이 큼.', related: ['amisulpride'] },
  { term: '루라시돈', en: 'lurasidone', def: '체중·혈당·지질 부담이 가장 적은 축의 2세대 항정신병약. 음식과 함께 먹어야 흡수됨.', related: ['lurasidone'] },
  { term: '브렉스피프라졸', en: 'brexpiprazole', def: '아리피프라졸의 후속 부분 작용제. 정좌불능이 적은 편이지만 조현병에 대한 효과 크기는 작은 편.', related: ['brexpiprazole'] },
  { term: '카리프라진', en: 'cariprazine', def: '도파민 D3 수용체를 D2보다 더 좋아하는 부분 작용제. 반감기가 몇 주에 이를 만큼 김.', related: ['cariprazine', 'negative-treatment-latest'] },
  { term: '지프라시돈', en: 'ziprasidone', def: '체중 증가가 가장 적은 축의 2세대 항정신병약. 심전도 QT 간격을 다른 약보다 더 늘림.', related: ['ziprasidone'] },
  { term: '클로자핀', en: 'clozapine', def: '치료저항성 조현병에서 효과가 확인된 유일한 약. 무과립구증 위험 때문에 정기 혈액검사를 하며 씀.', related: ['clozapine', 'treatment-resistant'] },
  { term: '자노멜린-트로스피움', en: 'xanomeline-trospium (Cobenfy)', def: '도파민 수용체가 아니라 무스카린(콜린성) 수용체를 겨냥한 조현병 약. 상품명 코벤피, 2024년 미국 승인.', related: ['new-drugs', 'dopamine-evolution', 'drug-pipeline'] },
  { term: '장기지속형 주사제', en: 'long-acting injectable (LAI)', def: '2주에서 6개월에 한 번 맞아 약 농도를 유지하는 주사 형태의 항정신병약. 먹는 약보다 재발·입원이 적다는 근거가 쌓임.', related: ['lai', 'medication-adherence'] },
  { term: '치료저항성 조현병', en: 'treatment-resistant schizophrenia (TRS)', def: '서로 다른 항정신병약 두 가지를 충분한 용량과 기간으로 써도 증상이 의미 있게 남는 상태. 기준은 2017년 TRRIP 국제 합의로 통일됨.', related: ['treatment-resistant', 'clozapine'] },
  { term: '추체외로 증상', en: 'extrapyramidal symptoms (EPS)', def: '항정신병약 부작용으로 생기는 떨림, 뻣뻣함, 안절부절못함 같은 움직임 문제. 급성 근긴장이상·파킨슨증·정좌불능·지연성 운동장애를 묶어 부름.', related: ['eps'] },
  { term: '급성 근긴장이상', en: 'acute dystonia', def: '약을 시작하거나 늘린 뒤 며칠 안에 목·턱·혀·눈이 한쪽으로 뒤틀리거나 굳는 부작용. 무섭지만 치료가 빠름.', related: ['eps'] },
  { term: '약물 유발 파킨슨증', en: 'drug-induced parkinsonism', def: '항정신병약 때문에 뻣뻣함, 느려짐, 손 떨림, 표정 없음이 생기는 부작용. 음성 증상·우울과 헷갈리기 쉬움.', related: ['eps', 'primary-secondary-negative'] },
  { term: '정좌불능', en: 'akathisia', def: '속에서 안달이 나 가만히 있지 못하고 다리를 계속 움직이게 되는 부작용. 아카티시아라고도 하며 불안·초조로 오해되기 쉬움.', related: ['eps', 'aripiprazole'] },
  { term: '지연성 운동장애', en: 'tardive dyskinesia (TD)', def: '약을 오래 쓴 뒤 생길 수 있는 입·혀·턱의 반복적인 불수의 움직임. 되돌리기 어려울 수 있어 AIMS로 정기 확인함. 지연성 운동이상이라고도 함.', related: ['eps', 'first-generation'] },
  { term: '신경이완제 악성 증후군', en: 'neuroleptic malignant syndrome (NMS)', def: '항정신병약 복용 중 고열과 온몸이 굳는 증상이 나타나는 드물지만 위험한 상태. 악성 긴장증과 거의 구분되지 않으며 응급.', related: ['neuroleptic-malignant-syndrome', 'catatonia', 'eps'] },
  { term: '대사증후군', en: 'metabolic syndrome', def: '복부 비만·혈압·혈당·지질 이상이 겹친 상태. 조현병이 있는 사람에게 흔하며 약 부작용과 생활 습관이 함께 관여함.', related: ['metabolic-side-effects', 'physical-health', 'diet-exercise'] },
  { term: '고프로락틴혈증', en: 'hyperprolactinemia', def: '항정신병약이 도파민을 막아 프로락틴이 올라가는 부작용. 월경 중단, 젖 분비, 성기능 저하, 뼈 약화가 생길 수 있음.', related: ['hyperprolactinemia'] },
  { term: 'QT 연장', en: 'QTc prolongation', def: '심전도의 QT 간격이 길어지는 심장 부작용. 늘리는 정도는 약마다 다르며, 지프라시돈·아미설프리드 같은 일부 약에서 더 두드러짐.', related: ['heart-and-antipsychotics', 'ziprasidone', 'amisulpride'] },
  { term: '항콜린 부작용', en: 'anticholinergic side effects', def: '입마름·변비·시야 흐림·배뇨 곤란·기억력 저하를 묶어 부르는 부작용. 여러 약의 이런 작용이 쌓인 정도를 항콜린 부담이라 함.', related: ['sedation-anticholinergic'] },
  { term: '무과립구증', en: 'agranulocytosis', def: '감염과 싸우는 백혈구(호중구)가 급격히 줄어드는 부작용. 클로자핀을 쓸 때 정기 혈액검사를 하는 이유.', related: ['clozapine'] },
  { term: '메트포르민', en: 'metformin', def: '당뇨약. 항정신병약으로 늘어난 체중과 인슐린 저항성을 줄이는 보조 약으로 메타분석 근거가 있음.', related: ['metabolic-side-effects', 'adjunct-medications'] },
  { term: '벤조디아제핀', en: 'benzodiazepine', def: '급성 초조·불안·불면에 단기로 쓰는 진정제. 긴장증에는 반응이 좋고, 의존과 내성이 단점.', related: ['benzodiazepines-sleep-meds', 'adjunct-medications', 'catatonia'] },
  { term: '기분안정제', en: 'mood stabilizer', def: '리튬·발프로산·라모트리진처럼 기분 변동을 다루는 약. 조현병에서는 기분 증상이 뚜렷할 때 주로 고려되며 근거는 제한적.', related: ['adjunct-medications', 'vs-bipolar'] },
  { term: 'CYP1A2', en: 'cytochrome P450 1A2', def: '클로자핀·올란자핀을 분해하는 간 효소. 담배 연기가 이 효소를 늘려 약 농도를 낮추므로 금연하면 농도가 크게 오를 수 있음.', related: ['smoking-caffeine-alcohol'] },

  /* ───────── 비약물 치료 ───────── */
  { term: 'CBTp', en: 'cognitive behavioural therapy for psychosis', def: '정신병에 대한 인지행동치료. 환청·망상을 설득으로 없애기보다 그 해석이 만드는 괴로움과 생활의 제약을 줄이며, 약을 대신하지 않고 그 위에 얹음.', related: ['cbtp', 'positive-self-help'] },
  { term: '가족 개입', en: 'family intervention', def: '가족이 병을 배우고 대화 방식을 바꾸도록 돕는 교육·치료. 재발을 줄이는 근거가 반복 확인됨.', related: ['family-intervention', 'family-first-steps'] },
  { term: '표출 정서', en: 'expressed emotion (EE)', def: '가족의 비판, 적대감, 지나친 감정적 개입의 정도. 높으면 조현병 재발을 예측하는 요인으로 확인됨.', related: ['family-intervention', 'leap-communication'] },
  { term: 'LEAP', en: 'Listen–Empathize–Agree–Partner', def: '듣기·공감하기·동의하기·함께하기의 네 단계로, 병을 인정하지 않는 사람과 다투지 않고 관계를 지키며 대화하는 방법.', related: ['leap-communication'] },
  { term: '사회기술 훈련', en: 'social skills training (SST)', def: '대화·거절 같은 대인 기술을 시범, 역할극, 피드백, 숙제로 반복 연습하는 재활 프로그램.', related: ['social-skills-training'] },
  { term: '인지재활', en: 'cognitive remediation (CRT)', def: '주의·기억·처리 속도·계획 같은 인지 기능을 치료자와 함께 전략을 익히며 훈련하는 치료. 직업재활과 묶을 때 효과가 커짐.', related: ['cognitive-remediation'] },
  { term: '지지 고용', en: 'individual placement and support (IPS)', def: '"먼저 일자리를 구하고 일하면서 지원받는" 취업 지원 방식. 개별 배치와 지원(IPS)이 표준 모델이고 직업재활 가운데 근거가 가장 강함.', related: ['supported-employment', 'work-study', 'vocational-rehab'] },
  { term: '전기경련치료', en: 'electroconvulsive therapy (ECT)', def: '전신마취와 근이완제 아래에서 뇌에 짧은 전기 자극을 주어 조절된 경련을 일으키는 치료. 긴장증, 치료저항성, 급성 위험 상황에 쓰임.', related: ['ect', 'catatonia'] },
  { term: 'rTMS', en: 'repetitive transcranial magnetic stimulation', def: '반복 경두개 자기자극. 자기 펄스로 뇌 특정 부위 활동을 조절하는 비침습 뇌 자극. 약한 전류를 쓰는 tDCS와 함께 연구됐지만 효과는 작고 연구마다 다름.', related: ['rtms-tdcs'] },
  { term: '아바타 치료', en: 'AVATAR therapy', def: '괴롭히는 목소리를 화면 속 얼굴로 만들고, 치료자가 연기하는 그 목소리에 당사자가 맞서 말하는 연습을 하는 치료. 영국에서 개발됨.', related: ['avatar-therapy'] },
  { term: '동료 지원', en: 'peer support', def: '같은 병을 겪고 회복 중인 사람이 다른 당사자를 돕는 활동. 희망·회복·자기효능감에서 긍정적 효과가 확인됨.', related: ['peer-support', 'loneliness-relationships'] },
  { term: '목소리 듣기 운동', en: 'Hearing Voices Movement', def: '목소리를 듣는 당사자들이 이끄는 국제 운동과 모임. 목소리를 의미 있는 인간 경험으로 보고 당사자의 해석을 존중함. 듣는 사람 운동이라고도 함.', related: ['living-with-voices', 'historical-figures'] },
  { term: '오픈 다이얼로그', en: 'Open Dialogue', def: '위기 때 하루 안에 당사자·가족·치료팀이 모여 모든 결정을 열린 대화로 내리는 서비스 방식. 핀란드 서부 라플란드에서 시작됨.', related: ['open-dialogue'] },
  { term: '적극적 지역사회치료', en: 'assertive community treatment (ACT)', def: '정신과 의사·간호사·사회복지사 등의 소규모 팀이 집으로 찾아가 치료와 생활을 돕는 모델. 입원 일수와 치료 이탈을 줄임. 한국에서는 정신건강복지센터의 사례관리가 그 역할을 함.', related: ['case-management-act', 'mental-health-center'] },
  { term: '낮병원', en: 'day hospital', def: '아침에 병원에 가서 치료와 프로그램을 받고 저녁에 집으로 돌아오는 형태. 입원과 외래의 중간 단계.', related: ['hospital-day-hospital'] },
  { term: '조기정신증 프로그램', en: 'early intervention in psychosis', def: '약, 심리치료, 가족 교육, 취업·학업 지원, 사례관리를 한 팀이 묶어 제공하는 첫 삽화 치료. 일반 진료보다 재입원과 중도 탈락을 줄임.', related: ['first-episode', 'early-detection'] },
  { term: 'WRAP', en: 'Wellness Recovery Action Plan', def: '웰니스 회복 실천 계획. 당사자 메리 엘런 코플랜드가 만든 자기관리 계획으로, 나를 지키는 도구·매일 유지 계획·유발 요인 등을 미리 적어 둠.', related: ['relapse-prevention-plan'] },

  /* ───────── 제도 ───────── */
  { term: '정신건강복지법', en: 'Mental Health Welfare Act', def: '「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」의 줄임말. 2017년 5월 시행됐고 입원의 종류, 당사자의 권리, 지역 서비스를 정함.', related: ['mental-health-welfare-act', 'admission-types'] },
  { term: '자의입원', def: '본인이 신청서를 내서 하는 입원. 퇴원을 신청하면 지체 없이 퇴원함.', related: ['admission-types', 'hospital-day-hospital'] },
  { term: '동의입원', def: '본인 신청과 보호의무자 동의로 하는 입원. 보호의무자 동의 없이 퇴원을 신청하면 전문의 판단으로 최대 72시간 거부될 수 있음.', related: ['admission-types'] },
  { term: '보호입원', def: '보호의무자에 의한 입원. 보호의무자 2명 이상의 신청과 전문의 진단이 필요하고, 치료가 필요한 정신질환과 자·타해 위험이 모두 있어야 함. 입원 중에도 퇴원 등 심사를 청구할 수 있음.', related: ['admission-types', 'hospital-day-hospital', 'acute-phase'] },
  { term: '행정입원', def: '지방자치단체장에 의한 입원. 전문의나 정신건강전문요원의 신청으로 시장·군수·구청장이 자·타해 위험이 의심되는 사람을 입원시킴.', related: ['admission-types', 'emergency-response'] },
  { term: '응급입원', def: '자·타해 위험이 크고 매우 급박할 때 의사와 경찰관의 동의로 하는 3일(공휴일 제외) 이내의 입원.', related: ['emergency-response', 'admission-types'] },
  { term: '입원적합성심사', def: '보호입원과 행정입원이 적합한지 외부 위원회가 심사하는 제도. 병원은 입원 3일 안에 신고하고, 당사자는 대면조사를 신청할 수 있음.', related: ['admission-types'] },
  { term: '사법입원', def: '법원 같은 사법기관이 강제입원 여부를 결정하는 방식. 2026년 10월 현재 시행 중인 법에는 없고 도입 논의가 이어지고 있음.', related: ['admission-types', 'controversies'] },
  { term: '산정특례', def: '조현병 스펙트럼 진단을 받아 등록하면 건강보험 진료비 본인부담을 10%로 낮춰 주는 한국의 제도.', related: ['special-calculation'] },
  { term: '정신건강복지센터', def: '시·군·구마다 있는 공공 정신건강 서비스 기관. 상담, 사례관리, 재활 프로그램, 위기 대응을 무료로 함.', related: ['mental-health-center', 'case-management-act'] },
  { term: '정신건강전문요원', def: '정신건강 분야의 간호사·사회복지사·임상심리사. 정신건강복지센터 등에서 약물 관리, 재발 예방, 사회 기능 회복을 도움.', related: ['case-management-act', 'mental-health-center'] },
  { term: '정신재활시설', def: '낮 시간 재활, 공동생활, 직업훈련 등을 돕는 지역의 복지시설. 생활시설, 주간재활시설·공동생활가정 같은 재활훈련시설, 중독자재활시설 등으로 나뉨.', related: ['rehab-facilities'] },
  { term: '동료지원가', def: '훈련을 받고 정신건강복지센터·병원·재활시설에서 상담, 프로그램 진행, 인식개선 활동을 하는 당사자. 동료지원인이라고도 함.', related: ['peer-support'] },
  { term: '정신장애 등록', def: '오랜 치료 뒤에도 생활에 큰 제약이 남았음을 공식으로 인정받는 절차. 2019년 등급제 폐지 뒤 "심한/심하지 않은" 장애로 나눔.', related: ['disability-registration'] },
  { term: '장애인연금', def: '심한 장애로 등록된 사람 가운데 소득이 기준 이하인 사람에게 세금으로 주는 연금. 국민연금 장애연금과는 다른 제도.', related: ['livelihood-pension', 'disability-registration'] },
  { term: '국민기초생활보장', def: '소득이 기준에 못 미치는 사람에게 생계·의료·주거·교육급여 등을 주는 제도. 선정기준은 해마다 고시됨.', related: ['livelihood-pension'] },
  { term: '성년후견', def: '정신적 제약으로 사무 처리 능력이 지속적으로 결여된 사람을 위해 가정법원이 후견을 정하는 민법 제도. 능력이 부족한 경우는 한정후견.', related: ['public-guardianship', 'money-management', 'parents-future-planning'] },
  { term: '정당한 편의', en: 'reasonable accommodation', def: '장애인차별금지법에 따라 사용자 등이 장애인에게 제공해야 하는 조정과 지원. 진단을 알린 뒤 직장·학교에 요청할 근거가 됨.', related: ['coping-at-work', 'work-study', 'insurance-employment'] },
  { term: '109', def: '자살예방 상담전화. 2024년 1월 기존 번호를 통합해 생겼고 24시간 운영됨.', related: ['crisis-hotlines', 'suicide-warning-signs'] },
  { term: '1577-0199', def: '정신건강위기상담전화. 109와 별도로 유지되며, 휴대전화로 걸면 가까운 정신건강복지센터로 연결됨.', related: ['crisis-hotlines', 'emergency-response'] },

  /* ───────── 연구·통계 ───────── */
  { term: '도파민 가설', en: 'dopamine hypothesis', def: '뇌 선조체에서 도파민이 지나치게 만들어지고 분비되는 것이 양성 증상과 관련된다는 설명. 수십 년에 걸쳐 점점 정밀하게 다듬어짐.', related: ['dopamine-hypothesis', 'dopamine-evolution'] },
  { term: '글루타메이트 가설', en: 'glutamate hypothesis', def: '뇌의 주요 흥분성 신호 물질인 글루타메이트, 특히 NMDA 수용체의 기능 저하가 음성·인지 증상까지 설명할 수 있다는 가설.', related: ['glutamate-hypothesis', 'glutamate-research'] },
  { term: 'NMDA 수용체', en: 'NMDA receptor', def: '글루타메이트를 받는 수용체의 하나로, 학습과 기억의 바탕인 시냅스 가소성에 핵심 역할을 함. 이를 막는 케타민이 조현병과 닮은 증상을 만듦.', related: ['glutamate-hypothesis', 'glutamate-research'] },
  { term: '신경발달 가설', en: 'neurodevelopmental hypothesis', def: '뇌가 만들어지는 과정의 작은 어긋남이 잠복하다가 청소년기 후반의 뇌 재편 과정에서 증상으로 드러난다는 가설.', related: ['neurodevelopment'] },
  { term: '시냅스 가지치기', en: 'synaptic pruning', def: '청소년기에 쓰지 않는 신경 연결(시냅스)을 대량으로 제거하는 과정. 너무 많이 잘라내면 조현병이 생길 수 있다는 가설로, 면역 유전자 C4와 뇌 면역세포인 미세아교세포가 관여한다는 발견이 근거를 더함.', related: ['neurodevelopment', 'inflammation-immune'] },
  { term: '스트레스-취약성 모델', en: 'stress-vulnerability model', def: '타고나거나 일찍 형성된 취약성 위에 스트레스가 쌓여 증상이 생긴다는 설명 틀. 1977년 주빈과 스프링이 제안함.', related: ['causes-overview', 'stress-management'] },
  { term: '비정상적 현저성', en: 'aberrant salience', def: '도파민이 맥락과 상관없이 분비되면서 의미 없는 자극에 강한 의미가 붙는다는 설명. 망상은 이 낯선 경험을 설명하려는 시도로 봄.', related: ['positive-neuroscience', 'dopamine-hypothesis'] },
  { term: '예측 처리', en: 'predictive processing', def: '뇌가 다음에 올 것을 예측하고 예측과 실제의 차이(예측 오차)로 배운다는 관점. 이 균형이 깨져 환각·망상이 생긴다는 설명에 쓰임.', related: ['positive-neuroscience', 'hollow-mask'] },
  { term: '유전율', en: 'heritability', def: '한 집단 안에서 사람들 사이의 위험 차이 중 유전적 차이로 설명되는 비율. "유전되면 걸릴 확률"이 아님.', related: ['genetics', 'myths'] },
  { term: '일치율', en: 'concordance rate', def: '쌍둥이 중 한 명이 병에 걸렸을 때 다른 한 명도 걸리는 비율. 일란성과 이란성의 차이로 유전의 몫을 추정함.', related: ['genetics', 'twin-studies'] },
  { term: 'GWAS', en: 'genome-wide association study', def: '전장 유전체 연관 분석. 병이 있는 사람과 없는 사람의 유전체를 넓게 비교해 위험과 관련된 흔한 변이를 찾는 연구 방법.', related: ['genetics', 'genomics'] },
  { term: '다유전자 위험 점수', en: 'polygenic risk score (PRS)', def: '수많은 흔한 위험 변이의 효과를 더해 낸 한 사람의 유전 점수. 연구에는 유용하지만 개인의 발병을 예측하거나 진단할 만큼 정확하지 않음.', related: ['genetics', 'genomics'] },
  { term: '희귀 변이', en: 'rare variants', def: '아주 드물지만 위험을 크게 올리는 유전 변이. 이런 변이를 가진 사람은 전체 조현병의 극히 일부.', related: ['genetics', 'genomics'] },
  { term: '내표현형', en: 'endophenotype', def: '병 자체는 아니지만 병의 유전적 취약성과 함께 다니는 특징. 증상 없는 가족에게서도 보임.', related: ['eye-tracking', 'precision-biomarkers'] },
  { term: 'PET', en: 'positron emission tomography', def: '양전자방출단층촬영. 방사성 표지 물질로 뇌의 도파민 기능이나 수용체 점유를 재며, 도파민 가설의 가장 직접적인 근거를 냄.', related: ['dopamine-hypothesis', 'antipsychotic-basics'] },
  { term: 'MRS', en: 'magnetic resonance spectroscopy', def: '자기공명분광법. MRI 장비로 살아 있는 사람의 뇌 속 글루타메이트 같은 화학물질 농도를 재는 방법.', related: ['glutamate-research'] },
  { term: 'ENIGMA', en: 'ENIGMA consortium', def: '세계 여러 센터의 뇌 MRI 자료를 합쳐 분석하는 국제 컨소시엄. 조현병 뇌 변화에 관해 가장 신뢰할 만한 숫자를 냄.', related: ['brain-changes', 'neuroimaging'] },
  { term: '메타분석', en: 'meta-analysis', def: '같은 질문을 다룬 여러 연구의 결과를 통계적으로 합쳐 분석하는 방법.', related: ['antipsychotic-basics', 'second-generation'] },
  { term: '네트워크 메타분석', en: 'network meta-analysis', def: '직접 맞대결하지 않은 치료들까지 공통 비교 대상을 거쳐 한꺼번에 비교하는 메타분석. 32개 항정신병약 비교가 대표적 예.', related: ['second-generation', 'side-effects-overview'] },
  { term: '체계적 고찰', en: 'systematic review', def: '정해진 방법으로 관련 연구를 빠짐없이 찾아 모으고 평가하는 연구. 결과를 통계로 합치면 메타분석이 됨.', related: ['first-episode', 'stigma-self-stigma'] },
  { term: '무작위 대조시험', en: 'randomized controlled trial (RCT)', def: '참여자를 무작위로 나눠 치료군과 비교군을 견주는 시험. 치료 효과를 가장 공정하게 확인하는 방법.', related: ['avatar-therapy', 'open-dialogue'] },
  { term: '위약 반응', en: 'placebo response', def: '효과 성분이 없는 가짜 약(위약)을 받은 사람도 좋아지는 현상. 최근 커지면서 신약 시험을 어렵게 만듦.', related: ['drug-pipeline', 'new-drugs'] },
  { term: '효과 크기', en: 'effect size', def: '두 집단 평균의 차이를 표준편차 단위로 나타낸 값. 대략 0.2는 작고 0.5는 중간, 0.8은 큰 차이.', related: ['brain-changes'] },
  { term: '상대위험', en: 'relative risk (RR)', def: '한 집단에서 어떤 일이 일어날 위험을 비교 집단의 위험으로 나눈 값. 1보다 작으면 위험이 줄었다는 뜻.', related: ['family-intervention', 'second-generation'] },
  { term: '오즈비', en: 'odds ratio (OR)', def: '어떤 일이 일어날 가능성(오즈)을 두 집단 사이에서 비교한 비. 1보다 크면 그 집단에서 더 잘 일어난다는 뜻.', related: ['alcohol-tobacco-cannabis'] },
  { term: '신뢰구간', en: 'confidence interval (CI)', def: '연구에서 얻은 추정값이 실제로 있을 법한 범위. 구간이 넓을수록 추정이 불확실함.', related: ['genetics'] },
  { term: '민감도와 특이도', en: 'sensitivity and specificity', def: '민감도는 병이 있는 사람 가운데 검사나 신호가 양성인 비율, 특이도는 병이 없는 사람 가운데 음성인 비율.', related: ['thought-interference', 'relapse-signs'] },
  { term: '유병률', en: 'prevalence', def: '특정 시점이나 기간에 병이 있는 사람의 비율. 일정 기간 새로 생기는 비율인 발생률과 구분됨.', related: ['epidemiology'] },
  { term: '출판 편향', en: 'publication bias', def: '효과가 있다는 결과가 더 잘 출판돼 전체 근거가 부풀려지는 현상.', related: ['immune-microbiome', 'drug-pipeline'] },
  /* ───────── 2026-10-24 추가 글 관련 ───────── */
  { term: '비확전', en: 'de-escalation', def: '화나 흥분이 커지기 전에 열을 낮추는 대응. 목소리를 낮추고, 거리와 출구를 지키고, 사실 논쟁 대신 감정을 한 문장으로 받아 주며, 요구는 하나씩만 하는 것이 요점.', related: ['anger-irritability', 'faq-anger', 'family-during-symptoms'] },
  { term: '기립성 저혈압', en: 'orthostatic hypotension', def: '앉거나 누웠다가 일어설 때 혈압이 떨어져 어지럽거나 눈앞이 캄캄해지는 부작용. 혈관의 알파1 수용체를 막는 항정신병약에서 생기기 쉽고, 치료 초기나 용량이 바뀔 때 잘 나타남.', related: ['orthostatic-hypotension', 'side-effects-overview', 'clozapine'] },
  { term: '타액 과다', en: 'hypersalivation (sialorrhea)', def: '침이 지나치게 많이 나오는 증상. 클로자핀의 흔한 부작용으로 특히 잠잘 때 심해져 베개가 젖을 정도가 될 수 있음.', related: ['clozapine-hypersalivation', 'clozapine'] },
  { term: '한정후견', def: '정신적 제약으로 사무 처리 능력이 부족한 사람을 위해 가정법원이 정하는 후견. 필요한 범위에서만 후견인의 동의가 필요하며, 능력이 지속적으로 결여된 경우의 성년후견보다 제한이 작음.', related: ['public-guardianship', 'money-management', 'parents-future-planning'] },
  { term: '특정후견', def: '일시적이거나 특정한 일에만 후원이 필요한 사람을 위한 후견. 본인 의사에 반해 할 수 없고, 가정법원이 기간과 범위를 정함. 세 후견 가운데 제한이 가장 작음.', related: ['public-guardianship', 'money-management', 'parents-future-planning'] },
  { term: '공공후견', def: '후견인을 세울 가족이나 비용이 없는 정신질환자를 위해 국가 지원으로 후견인을 연결해 주는 사업. 보건복지부 정신질환자 공공후견활동지원사업이 운영돼 왔음.', related: ['public-guardianship', 'money-management'] },
  { term: '장애인 신탁', en: 'trust for persons with disabilities', def: '장애인이 증여받은 재산을 신탁업자에게 맡기고, 신탁 이익 전부를 장애인이 받으며, 장애인이 사망할 때까지 유지하면 그 재산을 증여세 과세가액에 넣지 않는 상속세 및 증여세법상 제도.', related: ['parents-future-planning', 'money-management'] },
  { term: '지원주택', en: 'supported housing', def: '독립된 집에 살면서 필요한 만큼 생활·건강 지원 서비스를 함께 받는 주거 모델. 일부 지자체가 사업으로 운영하며, 현행 정신건강복지법의 정신재활시설 분류표에는 없음.', related: ['housing-support', 'housing-independent-living', 'rehab-facilities'] },
  { term: '활동지원', en: 'personal assistance service', def: '등록 장애인이 신청하는 돌봄 서비스. 활동지원사가 가정을 방문해 일상생활과 사회활동을 도움. 서비스 지원 종합조사로 시간이 정해지고 국민연금공단이 방문조사함.', related: ['activity-support-service', 'disability-registration'] },
  { term: '조기 발병 조현병', en: 'early-onset schizophrenia (EOS)', def: '18세 이전에 시작되는 조현병. 13세 이전에 시작하는 아주 이른 발병은 매우 드묾. 사춘기의 정상 변화나 다른 질환과 구분하는 데 시간이 걸릴 수 있음.', related: ['adolescent-onset', 'prodrome', 'early-detection'] },
  { term: '후기 발병 조현병', en: 'late-onset schizophrenia', def: '40세 이후에 처음 시작되는 조현병. 60세 이후 시작은 아주 늦은 발병 조현병 유사 정신증으로 따로 부름. 나이 들어 처음 생긴 환청·망상은 다른 원인도 함께 살펴야 함.', related: ['late-life', 'faq-late-onset'] },
  { term: '퇴원 계획', en: 'discharge planning', def: '퇴원 전에 첫 외래 날짜, 약, 지역 정신건강복지센터 연결, 위기 연락처를 미리 정하는 과정. 정신건강복지법은 본인 동의를 받아 퇴원 사실을 관할 센터에 알리게 함.', related: ['first-month-after-discharge', 'mental-health-center', 'hospital-stay-life'] },
  { term: '복약 순응', en: 'medication adherence', def: '처방대로 약을 먹는 정도. 깜빡 잊기, 부작용, 병식 저하 등으로 떨어질 수 있고, 약을 거르거나 끊으면 재발 위험이 크게 높아짐.', related: ['medication-adherence', 'missed-dose', 'relapse-signs'] },
  { term: '의료급여', def: '국민기초생활보장 급여의 하나로, 소득이 기준에 못 미치는 사람의 진료비를 지원하는 제도. 건강보험과 본인부담 체계가 다르며 선정기준은 해마다 고시됨.', related: ['drug-costs-coverage', 'fee-reductions', 'livelihood-pension'] },
  { term: '성기능 장애', en: 'sexual dysfunction', def: '성욕 저하, 발기·사정·오르가슴 장애 등. 항정신병약, 특히 프로락틴을 높이는 약에서 흔하지만 말하기 어려워 실제보다 적게 보고됨.', related: ['sexual-side-effects', 'hyperprolactinemia'] },
  { term: '수면제', en: 'hypnotics', def: '잠들게 하거나 잠을 유지하게 하는 약. 벤조디아제핀 계열과 졸피뎀 같은 비벤조디아제핀 계열이 있고, 오래 쓰면 의존·내성이 생길 수 있어 단기 사용이 원칙.', related: ['benzodiazepines-sleep-meds', 'sleep'] },
  { term: '증상 일기', en: 'symptom diary', def: '날마다 잠, 기분, 증상, 약 복용을 간단히 적는 자기관찰 도구. 재발 신호를 일찍 알아보고 진료 때 의사에게 전하는 데 쓰임. 종이나 앱으로 함.', related: ['symptom-diary-tools', 'managing-side-effects', 'relapse-prevention-plan'] },
  { term: '음악치료', en: 'music therapy', def: '훈련받은 치료사가 음악 활동으로 감정 표현, 관계, 동기를 돕는 비약물 치료. 음성 증상과 전반적 기능에 도움이 될 수 있다는 연구가 있음.', related: ['arts-music-therapy'] },
  { term: '의무기록', en: 'medical records', def: '의료기관이 진료 내용을 적어 보관하는 기록. 의료법에 따라 열람과 사본 발급은 원칙적으로 본인만 할 수 있고, 가족도 본인의 동의서가 필요함.', related: ['medical-records-privacy', 'faq-record-employment', 'family-during-symptoms'] },
  { term: '보호병동·개방병동', def: '보호병동은 출입을 통제해 급성기 안전을 지키는 정신과 입원 병동, 개방병동은 비교적 자유롭게 오갈 수 있는 병동. 상태가 좋아지면 보호병동에서 개방병동으로 옮기는 경우가 많음.', related: ['hospital-stay-life', 'hospital-day-hospital', 'admission-types'] },
  { term: '무스카린 수용체', en: 'muscarinic receptor', def: '아세틸콜린이 붙는 수용체의 한 종류로 침 분비, 장 운동, 동공 등을 조절함. 대부분의 항정신병약은 이 수용체를 막아 입이 마르게 하지만, 클로자핀은 일부 아형을 자극해 침이 늘어남.', related: ['clozapine-hypersalivation', 'sedation-anticholinergic'] },
  { term: 'Z-약물', en: 'Z-drug', def: '졸피뎀 등 비벤조디아제핀 계열 수면 전용 약. 벤조디아제핀과 같은 GABA 수용체에 작용하며, 오래 먹다 갑자기 끊으면 금단 증상이 올 수 있음.', related: ['benzodiazepines-sleep-meds', 'sleep'] },
  { term: '제네릭의약품', en: 'generic drug', def: '오리지널 약의 특허가 끝난 뒤 같은 성분·함량·제형으로 만든 복제약. 생물학적동등성이 입증되어야 허가되며, 보통 오리지널보다 약값이 낮음.', related: ['drug-costs-coverage'] },
  { term: '생물학적동등성', en: 'bioequivalence', def: '복제약이 오리지널 약과 같은 속도·양으로 몸에 흡수되는지 사람에게서 비교하는 시험과 그 결과. 제네릭의약품 허가의 핵심 조건.', related: ['drug-costs-coverage'] },
  { term: '하우징 퍼스트', en: 'Housing First', def: '증상 안정이나 금주를 조건으로 걸지 않고 집을 먼저 제공한 뒤 지원을 붙이는 주거 모델. 주거 유지에는 효과가 확인됐지만 증상 자체의 차이는 뚜렷하지 않았음.', related: ['housing-independent-living', 'housing-support'] },
  { term: '상병수당', en: 'sickness benefit', def: '일하다 아파서 일을 못 할 때 소득의 일부를 보전해 주는 제도. 국내에서는 보건복지부 시범사업 단계로, 대상 지역과 기준은 해마다 바뀜.', related: ['coping-at-work', 'livelihood-pension'] },
  { term: '임의후견', en: 'voluntary guardianship (후견계약)', def: '본인이 판단 능력이 있을 때 미리 후견인과 맡길 범위를 정해 두는 후견계약. 나중에 능력이 떨어지면 가정법원이 감독인을 선임하면서 효력이 시작됨.', related: ['public-guardianship', 'parents-future-planning', 'money-management'] },
  { term: '소득인정액', def: '국민기초생활보장 수급 여부를 판단하는 금액. 소득평가액에 재산의 소득환산액을 더해 계산하고, 급여별로 기준 중위소득의 일정 비율과 비교함.', related: ['livelihood-pension', 'housing-support'] },
  { term: '주거급여', def: '국민기초생활보장 급여의 하나로, 소득인정액이 기준 이하인 가구의 임차료를 지역별 기준임대료 범위에서 지원하는 제도. 선정기준은 해마다 고시됨.', related: ['housing-support', 'livelihood-pension'] },
  { term: '기준임대료', def: '주거급여에서 지역과 가구원 수에 따라 지원 상한으로 정한 임대료. 해마다 고시되며 서울이 가장 높음.', related: ['housing-support'] },
  { term: '주거유지지원서비스', def: '지원주택에 사는 사람이 집을 잃지 않도록 생활·건강·이웃 관계를 돕는 서비스. 서울시 지원주택은 공공임대주택에 이 서비스를 더한 제도.', related: ['housing-support', 'housing-independent-living'] },
  { term: '매입임대·전세임대', def: 'LH가 도심의 집을 사들여 시세보다 싸게 빌려 주는 매입임대와, 내가 찾은 집을 LH가 전세 계약해 다시 빌려 주는 전세임대. 소득·자산 기준을 갖춘 장애인 등록자는 우선순위에 들어감.', related: ['housing-support'] },
  { term: '서비스 지원 종합조사', def: '활동지원 같은 장애인 서비스의 지원 시간을 정하기 위한 조사. 국민연금공단이 방문해 일상·사회활동 기능을 평가하고 종합점수를 매김.', related: ['activity-support-service', 'disability-registration'] },
  { term: '긴급돌봄', def: '주 돌봄자의 갑작스러운 부재·질병 등으로 짧은 기간 도움이 필요할 때 재가 돌봄·가사·이동을 지원하는 보건복지부 사업. 자살 시도나 학대 같은 응급 상황은 응급 체계로 연결됨.', related: ['activity-support-service'] },
  { term: 'F코드', def: '국제질병분류에서 정신·행동 장애를 뜻하는 진단 코드 범주. 진료 기록과 건강보험 청구에 남지만, 의료법에 따라 본인 동의 없이 다른 사람이 볼 수 없음.', related: ['medical-records-privacy', 'faq-record-employment'] },
  { term: 'Z코드', def: '약 처방이 없는 정신과 외래 상담에 쓸 수 있는 일반 건강상담 코드. 2013년 4월부터 허용됐고, 약을 처방받으면 F코드가 유지됨.', related: ['medical-records-privacy'] },
  { term: '민감정보', def: '개인정보 보호법이 특별히 보호하는 정보로 건강 정보가 포함됨. 회사 등이 수집하려면 다른 동의와 따로 동의를 받아야 하고 법령 근거가 있어야 함.', related: ['medical-records-privacy', 'faq-record-employment'] },
  { term: '복지카드', def: '장애인 등록 때 받는 장애인등록증. 요금 감면·할인 대부분의 증빙이 되며, 고속도로 통행료 할인은 장애인 통합복지카드로 신청함.', related: ['fee-reductions', 'disability-registration'] },
  { term: '지속 관해', en: 'sustained remission', def: '증상이 오랫동안 거의 없는 상태가 이어지는 것. 아주 오래 앓은 중년·노년의 당사자에게서도 일어날 수 있다고 보고됨.', related: ['late-life', 'stable-phase', 'recovery'] },
  { term: 'CHIME', def: '개인적 회복의 다섯 과정인 연결(Connectedness), 희망(Hope), 정체성(Identity), 삶의 의미(Meaning), 힘(Empowerment)의 머리글자. 97편의 연구를 종합한 체계적 고찰에서 정리됨.', related: ['after-relapse', 'recovery', 'recovery-commonalities'] },
  { term: '편측화', en: 'lateralization', def: '한쪽 뇌가 특정 기능을 주로 맡는 것. 손잡이는 이를 밖에서 볼 수 있는 가장 쉬운 표지이며, 조현병에서 편측화가 덜 뚜렷하다는 가설이 있으나 효과 크기는 작음.', related: ['handedness', 'brain-changes'] },
  { term: '표준화발생비·표준화사망비', en: 'SIR / SMR', def: '어떤 집단에서 실제로 생긴 암 발생(또는 사망) 수를 나이·성별 구성을 맞춘 일반 인구에서 기대되는 수로 나눈 비. 1이면 일반 인구와 같다는 뜻.', related: ['cancer-incidence', 'life-expectancy'] },
  { term: '퇴원 사실 통보', def: '병원이 퇴원하는 사람의 동의를 받아 퇴원 사실을 관할 정신건강복지센터에 알리는 절차(정신건강복지법 제52조). 통보받은 센터는 본인이나 보호의무자와 상담해 재활 지원 방안을 마련함.', related: ['first-month-after-discharge', 'mental-health-center', 'faq-after-discharge'] },
  { term: '명령 환청', en: 'command hallucination', def: '무엇을 하라고 지시하는 내용의 환청. 두려움이나 불안과 겹치면 화와 짜증으로 드러날 수 있어, 내용을 의료진에게 말하는 것이 중요함.', related: ['anger-irritability', 'auditory-hallucination', 'living-with-voices'] },
  { term: '치료필요수', en: 'number needed to treat (NNT)', def: '한 사람에게서 원하는 효과를 더 얻기 위해 치료해야 하는 사람 수. 작을수록 효과가 큰 치료라는 뜻.', related: ['arts-music-therapy'] },
  { term: '예술 치료', en: 'arts therapies', def: '그림, 음악, 춤, 연극 같은 창작 활동을 훈련받은 치료사와 치료 관계 안에서 하는 비약물 치료. 음성 증상을 위해 고려하도록 권고한 지침이 있음.', related: ['arts-music-therapy', 'negative-treatment-latest'] },
  { term: '한국 조기 정신증 코호트 연구(KEPS)', en: 'Korean Early Psychosis Cohort Study (KEPS)', def: '조현병 스펙트럼·정신병적 장애의 첫 삽화 당사자를 2년 이상 추적하는 국내 전향적 관찰 연구. 2017년에 설계가 발표됨.', related: ['korea-research-landscape', 'first-episode'] },

  /* ───────── 2026-11-14 추가: 본문에 자주 나오는 말 ───────── */
  { term: '도파민', en: 'dopamine', def: '신경세포 사이에서 신호를 전하는 물질의 하나. 움직임·동기·보상·학습에 관여하고, "이것은 중요하다"는 표시를 붙이는 역할을 함.', related: ['dopamine-hypothesis', 'dopamine-evolution'], inline: false },
  { term: 'D2 수용체', en: 'dopamine D2 receptor', def: '도파민이 달라붙는 자리의 하나. 널리 쓰이는 항정신병약은 대부분 이 수용체를 막거나 조절해 환각·망상의 힘을 뺌.', related: ['antipsychotic-basics', 'dopamine-hypothesis'] },
  { term: '선조체', en: 'striatum', def: '피질 아래 뇌 깊은 곳의 부위. 양성 증상은 이곳에서 도파민이 지나치게 만들어지는 것과, 음성 증상은 이곳의 보상 기대 반응이 약한 것과 관련된다고 봄.', related: ['dopamine-hypothesis', 'negative-mechanism'] },
  { term: '전전두엽', en: 'prefrontal cortex', def: '노력과 보상의 값을 저울질하는 일에 관여하는 뇌 앞부분의 피질. 도파민 가설의 한 설명은 이곳의 도파민이 부족하다고 보며, rTMS가 음성 증상에 겨냥하는 부위이기도 함.', related: ['negative-mechanism', 'rtms-tdcs', 'dopamine-hypothesis'] },
  { term: '프로락틴', en: 'prolactin', def: '뇌하수체에서 나와 출산 뒤 젖을 만들게 하는 호르몬. 평소 도파민이 분비를 억누르는데, 항정신병약이 이를 풀면 올라가 월경·젖 분비·성기능에 영향을 줄 수 있음.', related: ['hyperprolactinemia', 'womens-health', 'sexual-side-effects'] },
  { term: '위약', en: 'placebo', def: '효과 성분이 없는 가짜 약. 임상시험에서 진짜 약을 받은 쪽과 견주어 약의 효과를 가리는 기준으로 씀.', related: ['positive-medication-response', 'drug-pipeline'], inline: false },
  { term: '코크란', en: 'Cochrane', def: '여러 무작위 시험을 모아 결과를 종합하는 체계적 고찰(코크란 리뷰·코크란 고찰). 치료 효과의 근거를 따질 때 자주 인용됨.', related: ['case-management-act', 'psychoeducation', 'arts-music-therapy'] },
  { term: 'NICE', en: 'National Institute for Health and Care Excellence', def: '영국 국립보건임상연구원. 정신증·조현병 치료, 술·약물 문제가 함께 있을 때의 치료 같은 진료지침을 내며, 이 백과가 권고의 근거로 자주 인용함.', related: ['cbtp', 'comorbid-substance-use', 'shared-decision-making'] },
  { term: '낙인', en: 'stigma', def: '정신질환에 대한 고정관념·편견이 차별로 이어지는 것. 사회의 공적 낙인, 제도의 구조적 낙인, 그것을 스스로 받아들이는 자기낙인으로 나눔.', related: ['stigma-self-stigma', 'media-reporting-guidelines'], inline: false },
  { term: '자기낙인', en: 'self-stigma', def: '사회의 편견을 내가 받아들여 스스로를 낮추는 것. 편견을 알고, 동의하고, 나에게 적용하며 생기고, 희망과 자존감을 깎지만 줄이는 프로그램이 있음.', related: ['stigma-self-stigma', 'diagnosis-emotions'] },
  { term: '조증', en: 'mania', def: '기분이 크게 들뜨는 상태. 양극성 장애의 한 축이며, 심해지면 환각·망상이 함께 나타날 수 있어 조현병과 구분이 필요함.', related: ['vs-bipolar', 'grandiose-delusion'], standalone: true },
  { term: '양극성 장애', en: 'bipolar disorder', def: '기분이 크게 들뜨는 조증과 가라앉는 우울이 번갈아 오는 병. 기분 삽화 중에 환각·망상이 생길 수 있어, 정신병 증상이 기분 삽화와 같이 오가는지로 조현병과 구분함.', related: ['vs-bipolar', 'misdiagnosis', 'vs-schizoaffective'] },
  { term: '항우울제', en: 'antidepressant', def: '우울을 다루는 약. 조현병에서는 우울이나 음성 증상에 항정신병약과 함께 쓰는 보조 약으로 연구됐고, 효과는 작지만 일관된 편.', related: ['adjunct-medications', 'negative-vs-depression'] },
  { term: '편집증', en: 'paranoia', def: '남이 나를 나쁘게 보거나 해치려 한다는 의심. 가벼운 의심부터 확신으로 굳은 피해망상까지 일반 인구 안에 연속선으로 퍼져 있다고 봄. 잠이 무너지면 심해지기 쉬움.', related: ['persecutory-delusion', 'sleep'] },
  { term: '현실 검증', en: 'reality testing', def: '지금 겪는 것이 바깥 현실인지 내 뇌가 만든 것인지 가리는 힘. 급성기에는 흔들리고, 치료가 진행되면 경험과 해석을 떼어 놓는 힘이 돌아오는 경우가 많음.', related: ['positive-overview', 'positive-self-help'] },
  { term: '정신병적 경험', en: 'psychotic experiences', def: '가끔 들리는 목소리, 감시당하는 느낌처럼 진단 문턱 아래에 있는 정신병 같은 경험. 일반 인구에서도 드물지 않고 대부분 지나감.', related: ['spectrum', 'sleep'] },
  { term: '약화된 정신병 증후군', en: 'attenuated psychosis syndrome', def: '망상·환각 같은 경험이 있지만 강도나 빈도가 진단 문턱에 못 미치고 도움을 구하는 상태. DSM-5에 추가 연구가 필요한 상태로 실린 연구용 범주이며 정식 진단은 아님.', related: ['spectrum', 'prodrome'] },
  { term: '작업기억', en: 'working memory', def: '정보를 몇 초 동안 머릿속에 붙들고 조작하는 "작업대" 같은 인지 기능. 약하면 긴 설명을 따라가기 어려워, 짧게 끊어 듣고 적으며 듣는 것이 도움이 됨.', related: ['cognitive-domains', 'cognitive-overview'] },
  { term: '처리 속도', en: 'processing speed', def: '정보를 받아들이고 반응하기까지의 빠르기. 조현병의 인지 영역 가운데 가장 크게 떨어지는 영역으로 보고됨. 느리다는 것은 같은 결론에 시간이 더 필요하다는 뜻.', related: ['cognitive-domains', 'cognitive-overview'] },
  { term: '실행 기능', en: 'executive function', def: '목표를 세우고 순서를 정하고 상황이 바뀌면 계획을 고치는 힘. 약하면 요리처럼 여러 단계를 관리하는 일, 서류 절차, 예산 짜기가 어려워짐.', related: ['cognitive-domains', 'cognitive-remediation'] },
  { term: 'MRI', en: 'magnetic resonance imaging', def: '뇌 구조를 찍는 영상 검사. 모든 사람에게 하지는 않고, 다른 원인이 의심될 때 뇌종양·뇌전증 등을 가리는 데 씀. 연구에 많이 쓰이지만 아직 조현병 진단 도구는 아님.', related: ['rule-out-conditions', 'diagnostic-process', 'neuroimaging'] },
  { term: '뇌파', en: 'electroencephalography (EEG)', def: '경련·의식 변화·발작성 증상이 있을 때 뇌전증이나 뇌염 같은 다른 원인을 가리려고 하는 뇌 검사. 모든 사람에게 하지는 않음.', related: ['rule-out-conditions', 'diagnostic-process'] },
  { term: '뇌전증', en: 'epilepsy', def: '경련이나 멍해지는 발작을 일으키는 뇌 질환. 측두엽 뇌전증은 냄새·맛 환각이나 정신병 증상을 동반할 수 있어, 첫 진단 때 가려야 할 질환에 듦.', related: ['rule-out-conditions'] },
  { term: '섬망', en: 'delirium', def: '수술·감염·약 같은 몸의 변화 때문에 의식이 흐려지고 주의가 흩어지는 상태. 하루 안에도 좋아졌다 나빠졌다 해서 정신과 증상과 헷갈리기 쉬움.', related: ['other-medical-care', 'rule-out-conditions'] },
  { term: '사례관리', en: 'case management', def: '병원 밖에서 치료와 생활을 이어 주는 사람(사례관리자)을 두는 체계. 한국에서는 정신건강복지센터가 등록한 사람에게 무료로 상담·방문·위기 대응을 함.', related: ['case-management-act', 'mental-health-center'] },
  { term: '주간재활', en: 'day rehabilitation', def: '정신건강복지센터나 정신재활시설(주간재활시설)에서 낮 동안 운영하는 재활 프로그램. 병원이 아닌 복지 체계라 대체로 무료이며 사회기술훈련·직업 준비·운동 등을 함.', related: ['hospital-day-hospital', 'rehab-facilities'] },
  { term: '공유 의사결정', en: 'shared decision-making', def: '의사의 의학 지식과 당사자의 삶·선호를 합쳐 치료를 고르는 방식. 함께 결정하기라고도 함. 의사가 정해 주는 것도, 당사자 혼자 정하는 것도 아님.', related: ['shared-decision-making', 'managing-side-effects'] },
  { term: '약 농도 검사', en: 'therapeutic drug monitoring (TDM)', def: '피를 뽑아 그 안에 약이 얼마나 들어 있는지 재고 해석해 치료를 맞추는 검사. 당사자를 의심하려는 것이 아니라 효과가 부족하거나 부작용이 큰 원인을 찾는 도구.', related: ['drug-level-test', 'treatment-resistant'] },

  /* ───────── 2026-11-14 추가: 새 글의 몸·치료 용어 ───────── */
  { term: '다음증', en: 'polydipsia', def: '목마름과 상관없이 몸에 필요한 것보다 훨씬 많은 물을 마시는 상태. 조현병을 오래 앓은 사람에게서 드물지 않게 보이며, 일부는 저나트륨으로 이어짐.', related: ['polydipsia-hyponatremia'] },
  { term: '저나트륨', en: 'hyponatremia', def: '혈액의 나트륨이 낮은 상태. 물을 지나치게 마셔 나트륨이 묽어지면 두통·메스꺼움이 오고, 심하면 혼란·경련·혼수로 이어지는 물 중독이 올 수 있음.', related: ['polydipsia-hyponatremia'] },
  { term: '열사병', en: 'heatstroke', def: '더위로 생기는 온열질환 가운데 의식이 흐려지거나 잃고 몸이 매우 뜨거워지는 응급 상태. 바로 119에 연락하고 기다리는 동안 몸을 식힘. 일부 정신과 약은 더위에 약하게 만듦.', related: ['heat-and-medication'] },
  { term: '심근염', en: 'myocarditis', def: '클로자핀에서 드물게, 주로 시작 초기에 생기는 심장 부작용. 가슴 통증·빈맥·두근거림·숨참·열 같은 증상이 있으면 의심하므로 곧바로 의료진에게 알림.', related: ['heart-and-antipsychotics', 'clozapine'] },
  { term: '빈맥', en: 'tachycardia', def: '맥박이 빨라지는 것. 약의 항콜린 작용이나 기립성 저혈압에 대한 반응으로 생길 수 있고 클로자핀에서 특히 흔함. 맥박을 재서 진료 때 숫자로 알림.', related: ['heart-and-antipsychotics', 'clozapine'] },
  { term: '정신교육', en: 'psychoeducation', def: '병과 약, 재발 신호, 위기 때 할 일을 당사자와 가족이 여러 번에 걸쳐 체계적으로 배우는 치료. 정신건강복지센터나 담당 의사에게 프로그램을 물어볼 수 있음.', related: ['psychoeducation', 'insight'] },
  { term: 'PTSD', en: 'post-traumatic stress disorder', def: '외상 후 스트레스 장애. 외상 기억이 되살아나는 병으로, 환각처럼 보이는 경험이 있어 조현병과 헷갈리기도 함. 정신증 경험이나 강제 입원 같은 치료 과정이 외상이 되기도 함.', related: ['trauma-and-psychosis', 'vs-autism-borderline'] },
  { term: '아동기 역경', en: 'childhood adversity', def: '학대·방임·괴롭힘·부모의 죽음 같은 어린 시절의 심각한 경험. 정신병 위험을 높이지만 보통의 양육을 뜻하지 않으며, 역경을 겪은 아이 대부분은 정신병에 걸리지 않음.', related: ['social-factors', 'trauma-and-psychosis'] },
  { term: '모호한 상실', en: 'ambiguous loss', def: '끝이 분명하지 않은 상실. 사람은 곁에 있는데 예전의 모습과 함께 그리던 미래를 잃은 것 같은 가족의 슬픔을 설명하는 말로, 슬픔이 마무리되지 않는 것은 애도의 실패가 아님.', related: ['family-grief'] },

  /* ───────── 2026-11-14 추가: 제도·권리 ───────── */
  { term: '보호의무자', def: '정신질환이 있는 사람의 치료와 권리를 곁에서 챙기도록 정신건강복지법이 정한 사람. 민법상 후견인이나 부양의무자가 되며, 입원을 신청할 수 있지만 본인 뜻 존중과 퇴원 협조 의무가 먼저임.', related: ['guardian-duties', 'admission-types'] },
  { term: '절차조력인', def: '입원·퇴원 때 당사자의 동의를 받아 서류 작성, 심사 참여, 청구, 통신·면회를 돕는 사람. 정신건강복지법에 근거하며 병원은 이 서비스를 알려야 함.', related: ['admission-types', 'guardian-duties', 'mental-health-welfare-act'] },
  { term: '국가인권위원회', en: 'National Human Rights Commission of Korea', def: '인권 침해와 차별에 대한 진정을 받아 조사하는 기관. 정신의료기관·정신요양시설 같은 곳에서 인권 침해를 당하거나 알게 된 사람이 진정할 수 있음. 인권상담전화 1331.', related: ['admission-types', 'habeas-corpus-relief', 'insurance-employment'] },
  { term: '인신보호 구제청구', def: '본인 뜻과 다르게 병원이나 시설에 머물 때 그 수용이 법에 맞는지 법원에 직접 판단을 구하는 제도. 본인, 가족, 동거인, 시설 종사자 등이 청구할 수 있음.', related: ['habeas-corpus-relief', 'guardian-duties'] },
  { term: '권역정신응급의료센터', def: '자해·자살 시도처럼 몸의 응급처치와 정신과 치료가 함께 필요한 사람을 위한 응급실. 응급의학과와 정신건강의학과가 함께 진료함. 다쳤거나 약을 많이 먹었다면 어느 병원인지보다 먼저 119.', related: ['psychiatric-emergency-system', 'treatment-cost-support'] },
  { term: '동료지원쉼터', def: '일시적인 정신건강 위기를 겪는 사람을 잠시 보호하며, 정신질환을 겪었거나 겪고 있고 양성과정을 마친 동료지원인이 상담하는 곳. 가까운 쉼터는 정신건강복지센터나 1577-0199에 물어봄.', related: ['psychiatric-emergency-system', 'mental-health-welfare-act'] },
  { term: '정신질환 치료비 지원사업', def: '응급입원·행정입원, 발병 초기 치료, 외래치료 지원 등의 치료비 본인부담을 국가와 지자체가 덜어 주는 사업. 정신건강복지센터 등 기관 등록이 요건이고 기준은 지역과 해마다 다름.', related: ['treatment-cost-support', 'medical-cost-safety-net'] },
  { term: '본인부담상한제', def: '1년 동안 낸 건강보험 급여 본인부담금 합계가 개인별 상한액을 넘으면 넘은 돈을 국민건강보험공단이 부담하는 제도. 비급여 등은 합계에 들어가지 않음.', related: ['medical-cost-safety-net'] },
  { term: '재난적의료비', def: '소득에 비해 큰 의료비로 어려운 가구에 의료비 일부를 지원하는 제도. 질환·소득·재산·의료비 부담 기준을 모두 채워야 하며 비급여 일부도 지원 범위에 듦.', related: ['medical-cost-safety-net'] },
  { term: '긴급복지 의료지원', def: '주소득자의 사망·실직, 중한 질병 같은 위기로 생계가 어려워진 저소득 가구의 입원·수술 의료비를 일시적으로 돕는 제도. 시·군·구나 보건복지상담센터 129에 요청함.', related: ['medical-cost-safety-net'] },
  { term: '심리상담 바우처', def: '우울·불안 같은 정서적 어려움이 있는 사람에게 전문 심리상담을 지원하는 정신건강 심리상담 바우처 사업. 조현병 당사자는 대개 대상이 아니지만 돌봄에 지친 가족은 신청할 수 있음.', related: ['counseling-voucher-and-screening', 'caregiver-burnout'] },
  { term: '가족돌봄휴가', def: '회사에 다니는 사람이 질병·사고·노령으로 돌봄이 필요한 가족을 위해 쓰는 법정 휴가. 더 길게 쉬는 가족돌봄휴직과 근로시간 단축도 있으며, 형제자매는 법이 정한 대상 가족이 아님.', related: ['family-care-leave'] },
  { term: '고지 의무', en: 'duty of disclosure', def: '보험에 가입할 때 보험사가 묻는 질문에 사실대로 답할 의무. 고의나 중대한 과실로 중요한 사항을 알리지 않거나 틀리게 알리면 보험사가 계약을 해지할 수 있고, 그러면 보험금을 못 받을 수 있음.', related: ['insurance-employment', 'faq-insurance'] },
  { term: '심신미약', def: '심신장애로 사물을 변별하거나 의사를 결정할 능력이 미약한 상태를 가리키는 형법의 말. 형을 줄일 수 있으며, 진단명이 아니라 그때의 능력을 사건마다 법원이 판단함.', related: ['justice-system'] },
  { term: '치료감호', def: '심신장애로 금고 이상의 형에 해당하는 죄를 지었고 치료가 필요하며 재범 위험성이 있을 때 치료감호시설에 수용해 치료하는 제도. 검사가 청구하고 법원이 판결로 정함.', related: ['justice-system'] },
];

