      var r = rootOf(w);
      /* '하/되' 만 다른 꼴은 같은 뿌리로(입원되면 = 입원하면) */
      if (r && HADOE[r.slice(-2)] && r.length >= 4 && (r.slice(-2) === '되면' || r.slice(-2) === '돼도')) r = hadoe(r);
      if (r && out.indexOf(r) < 0) out.push(r);
