    if (!U.qs('.jhb-stale', app) && target.parentNode) {
      target.parentNode.insertBefore(el('p.notice.jhb-stale', { role: 'status', style: 'margin:16px 0' }, [msg + ' ', reloadBtn()]), target);
    }
